parameters.inputSchema:
{
  "name": "resume_screening_evaluation",
  "description": "Analyzes a candidate's resume against a job description and outputs strengths, weaknesses, risk/reward assessment, and an overall fit score.",
  "type": "object",
  "properties": {
    "candidate_strengths": {
      "type": "array",
      "description": "A list of specific strengths or qualifications that match the job description.",
      "items": {
        "type": "string"
      }
    },
    "candidate_weaknesses": {
      "type": "array",
      "description": "A list of areas where the candidate falls short or lacks alignment with the job requirements.",
      "items": {
        "type": "string"
      }
    },
    "risk_factor": {
      "type": "object",
      "description": "An evaluation of the potential risks of hiring this candidate.",
      "properties": {
        "score": {
          "type": "string",
          "enum": ["Low", "Medium", "High"],
          "description": "The risk level of hiring this candidate."
        },
        "explanation": {
          "type": "string",
          "description": "A brief explanation of the worst-case scenario if the candidate is hired."
        }
      },
      "required": ["score", "explanation"]
    },
    "reward_factor": {
      "type": "object",
      "description": "An evaluation of the potential upside of hiring this candidate.",
      "properties": {
        "score": {
          "type": "string",
          "enum": ["Low", "Medium", "High"],
          "description": "The reward level of hiring this candidate."
        },
        "explanation": {
          "type": "string",
          "description": "A description of the best-case scenario and whether the candidate is a short-term or long-term fit."
        }
      },
      "required": ["score", "explanation"]
    },
    "overall_fit_rating": {
      "type": "integer",
      "description": "A rating from 0 to 10 indicating how well the candidate matches the job description.",
      "minimum": 0,
      "maximum": 10
    },
    "justification_for_rating": {
      "type": "string",
      "description": "A summary explaining why the candidate received the specific fit rating, referencing resume and job description alignment."
    }
  },
  "required": [
    "candidate_strengths",
    "candidate_weaknesses",
    "risk_factor",
    "reward_factor",
    "overall_fit_rating",
    "justification_for_rating"
  ]
}

parameters.jsCode:
// 1. Ambil Subjek Email Pelamar SECARA LANGSUNG dari node 'Receive Resume'
let subject = $('Receive Resume').first().json.subject || "";
let subjectLower = subject.toLowerCase();

// 2. Ambil seluruh baris pengaturan dari node Google Sheets sebelumnya
let configRows = $input.all(); 

// 3. Siapkan variabel penampung default
let thresholdSkor = 7; 
let fileIdJd = "";
let posisiTerdeteksi = "General";
let templateLolos = "";
let templateTolak = "";
let posisiDitemukan = false;

// 4. Looping untuk membaca tab Config
for (let i = 0; i < configRows.length; i++) {
    let row = configRows[i];
    let parameter = row.json["PARAMETER"] || "";
    let nilai = row.json["NILAI / VALUE"] || "";

    // Tarik nilai Parameter Umum
    if (parameter === "Threshold Skor Minimum") thresholdSkor = parseFloat(nilai);

    // Tarik Template Email
    if (parameter.includes("Template Email — LOLOS")) {
        templateLolos = nilai !== "" ? nilai : (configRows[i+1] ? configRows[i+1].json["PARAMETER"] : "");
    }
    if (parameter.includes("Template Email — PENOLAKAN")) {
        templateTolak = nilai !== "" ? nilai : (configRows[i+1] ? configRows[i+1].json["PARAMETER"] : "");
    }

    // Logika Pencocokan Posisi Aktif
    let namaPosisi = row.json["PARAMETER"] || "";        
    let pathJd = row.json["NILAI / VALUE"] || "";        
    let status = row.json["TIPE DATA"] || "";            
    let keyword = row.json["WAJIB?"] || "";              

    if (status === "AKTIF" && keyword !== "" && namaPosisi !== "NAMA POSISI" && !posisiDitemukan) {
        let keywordArray = keyword.split(",");
        for (let kw of keywordArray) {
            let kataKunciBersih = kw.trim().toLowerCase();
            if (kataKunciBersih !== "" && subjectLower.includes(kataKunciBersih)) {
                posisiTerdeteksi = namaPosisi;
                fileIdJd = pathJd; 
                posisiDitemukan = true; 
                break; 
            }
        }
    }
}

// [PERBAIKAN] Fallback jika template dari Google Sheets kosong karena merged cell
if (templateLolos === "") {
    templateLolos = "Halo [NAMA_KANDIDAT],<br><br>Selamat! Anda dinyatakan LOLOS seleksi awal untuk posisi [NAMA_POSISI] di [NAMA_PERUSAHAAN]. Tim kami akan segera menghubungi Anda untuk tahap wawancara.<br><br>Salam hangat,<br>Tim HR [NAMA_PERUSAHAAN]";
}

if (templateTolak === "") {
    templateTolak = "Halo [NAMA_KANDIDAT],<br><br>Terima kasih telah melamar posisi [NAMA_POSISI] di [NAMA_PERUSAHAAN]. Setelah meninjau profil Anda, mohon maaf kualifikasi Anda saat ini belum sesuai dengan kebutuhan kami.<br><br>Semoga sukses di perjalanan karier Anda selanjutnya.<br><br>Salam,<br>Tim HR [NAMA_PERUSAHAAN]";
}

// [PERBAIKAN ERROR] Logika dinamis untuk menarik teks Resume dari jalur yang aktif (Normal atau OCR)
let resumeData = "";

// Coba ambil dari jalur Normal terlebih dahulu
try {
    resumeData = $('Set Resume Normal').first().json.resume;
} catch(e) {
    // Abaikan error jika kandidat tidak melewati jalur normal
}

// Jika masih kosong, ambil dari jalur OCR
if (!resumeData) {
    try {
        resumeData = $('Set Resume OCR').first().json.resume;
    } catch(e) {
        // Abaikan error jika kandidat tidak melewati jalur OCR
    }
}

// 5. Kembalikan 1 Item JSON bersih ke node selanjutnya
return {
    json: {
        posisi_dilamar: posisiTerdeteksi,
        file_id_jd: fileIdJd, // <--- KEMBALIKAN ADA _jd DI BELAKANGNYA
        threshold_skor: thresholdSkor,
        template_lolos: templateLolos,
        template_tolak: templateTolak,
        resume: resumeData 
    }
};
